"""Build dependency-free, GitHub Pages-compatible Persian cafe pages."""
from pathlib import Path
from html import escape
import json
P=Path(__file__).resolve().parents[1]
BASE='https://mahdi-1949.github.io/cafeshop/'
def img(name,alt,cls='',eager=False):
 return f'<img src="assets/images/{name}.jpg" alt="{alt}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def link(url,text,cls=''):return f'<a class="{cls}" href="{url}">{text}<span aria-hidden="true">↖</span></a>'
def eyebrow(text):return f'<span class="eyebrow">{text}</span>'
def brand():return '<a class="brand" href="index.html" aria-label="کافه مکث؛ صفحه اصلی"><span class="brand-symbol" aria-hidden="true">مـ</span><span>مکث<small>قهوه و زندگی</small></span></a>'
navlinks=[('index.html','خانه'),('about.html','داستان مکث'),('gallery.html','قاب‌های کافه'),('journal.html','مجلهٔ مکث')]
def header(page):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if page==url else '')+f'>{name}</a>' for url,name in navlinks)
 return f'''<a href="#main" class="skip">رفتن به محتوای اصلی</a><div class="topline"><span>کمی دور از شتاب، کمی نزدیک‌تر به خودت.</span><a href="journal.html">چند خط کنار قهوه ↖</a></div><header class="site-header"><div class="header-inner">{brand()}<nav id="navigation" aria-label="منوی اصلی">{links[:links.find('<a href="about.html"')]}<div class="mega-wrap"><button class="mega-toggle" aria-controls="mega-menu" aria-expanded="false">منوی کافه <span aria-hidden="true">⌄</span></button><div id="mega-menu" class="mega-menu" hidden><div class="mega-intro">{eyebrow('به سلیقهٔ تو')}<h2>امروز چه<br>طعمی می‌چسبد؟</h2>{link('menu.html','دیدن تمام منو','text-link')}</div><div class="mega-links"><a href="menu.html?category=coffee"><b>۰۱</b><span>قهوه‌های گرم<small>از اسپرسو تا قهوهٔ دمی</small></span>↖</a><a href="menu.html?category=cold"><b>۰۲</b><span>نوشیدنی‌های سرد<small>یک جرعه خنکی</small></span>↖</a><a href="menu.html?category=breakfast"><b>۰۳</b><span>صبحانه و میان‌وعده<small>برای شروع‌های آرام</small></span>↖</a><a href="menu.html?category=cake"><b>۰۴</b><span>کیک و شیرینی<small>همراه شیرین فنجانت</small></span>↖</a></div><a class="mega-photo" href="menu.html?category=coffee">{img('coffee-1','لاته با طرح شیر')}<span>یک لاته، یک مکث کوتاه ↖</span></a></div></div>{links[links.find('<a href="about.html"'):]}</nav><a class="header-cta" href="visit.html">برای یک قرار <span>↖</span></a><button class="nav-toggle" aria-controls="navigation" aria-expanded="false" aria-label="باز کردن منو"><span></span><span></span></button></div></header>'''
def footer():
 return f'''<section class="closing"><div>{eyebrow('قرارهای خوب، از یک فنجان شروع می‌شوند.')}<h2>برای یک <em>مکث</em>، وقت هست.</h2></div>{link('menu.html','طعم بعدی‌ات را پیدا کن','button cream')}</section><footer class="site-footer"><div class="footer-grid"><div class="footer-brand">{brand()}<p>یک جای دنج میان شلوغی روز.<br>برای قهوه، گفت‌وگو و کمی زندگی.</p><span class="footer-seal" aria-hidden="true">آهسته‌تر<br>خوش‌طعم‌تر ✶</span></div><div><h2>در مکث بگرد</h2><a href="menu.html">منوی کافه</a><a href="about.html">داستان مکث</a><a href="gallery.html">قاب‌های کافه</a><a href="journal.html">مجلهٔ مکث</a></div><div><h2>قرار و گفت‌وگو</h2><a href="visit.html">برنامه‌ریزی یک قرار</a><a href="contact.html">تماس و نشانی</a><a href="faq.html">پرسش‌های متداول</a><a href="privacy.html">حریم خصوصی</a></div><div class="footer-note"><h2>این‌جا، جای کافهٔ شماست</h2><p>مکث یک نمونه‌کار طراحی است.<br>نام، منو و قیمت‌ها پیشنهادی‌اند؛ اطلاعات تماس واقعی پس از شخصی‌سازی اضافه می‌شوند.</p><a href="contact.html" class="text-link">بیشتر بدان ↖</a></div></div><div class="footer-bottom"><span>© <span data-year>۲۰۲۶</span> کافه مکث · تصاویر از Unsplash</span><p>طراحی و سئو سایت توسط: <a href="https://mahditavakoli.ir/" target="_blank" rel="noopener noreferrer">مهدی توکلی</a></p><a href="#top" class="back-top" aria-label="رفتن به بالای صفحه">↑</a></div></footer><dialog id="photo-dialog"><button class="close-dialog" aria-label="بستن تصویر">×</button><img alt=""><div class="dialog-bottom"><p></p><span id="photo-position"></span><div><button id="photo-prev" aria-label="تصویر قبلی">→</button><button id="photo-next" aria-label="تصویر بعدی">←</button></div></div></dialog><div id="toast" role="status"></div>'''
def page(file,title,desc,body):
 canonical=BASE+('' if file=='index.html' else file)
 html=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | کافه مکث</title><meta name="description" content="{desc}"><meta name="theme-color" content="#302820"><meta property="og:title" content="{title} | کافه مکث"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}assets/images/hero.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="{canonical}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/font.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body id="top" data-page="{file}">{header(file)}<main id="main">{body}</main>{footer()}</body></html>'''
 (P/file).write_text(html)
def mast(kicker,title,desc,photo='cup'):
 return f'<section class="page-mast"><div class="mast-copy"><div class="breadcrumbs"><a href="index.html">خانه</a><span>/</span><span>{kicker}</span></div>{eyebrow(kicker)}<h1>{title}</h1><p>{desc}</p><span class="mast-star" aria-hidden="true">✶</span></div><div class="mast-photo">{img(photo,kicker,eager=True)}</div></section>'
def menu_controls(home=False):
 return '''<div class="menu-toolbar"><div class="menu-tabs" role="group" aria-label="دسته‌بندی منو"><button class="active" data-category="coffee" aria-pressed="true">قهوه‌های گرم</button><button data-category="cold" aria-pressed="false">نوشیدنی‌های سرد</button><button data-category="breakfast" aria-pressed="false">صبحانه و میان‌وعده</button><button data-category="cake" aria-pressed="false">کیک و شیرینی</button>'''+('' if home else '<button data-category="all" aria-pressed="false">همهٔ منو</button>')+'''</div>'''+('' if home else '<label class="search-label"><span class="sr-only">جست‌وجوی منو</span><input type="search" id="menu-search" placeholder="دنبال چه طعمی هستی؟" autocomplete="off"><span aria-hidden="true">⌕</span></label>')+'''</div><p id="menu-result" class="sr-only" role="status"></p><div id="menu-grid" class="menu-grid"></div><div id="menu-empty" class="empty-state" hidden><span>⌕</span><h3>این طعم را پیدا نکردیم.</h3><p>یک نام کوتاه‌تر بنویس یا همهٔ منو را ببین.</p><button class="text-link" id="reset-search">پاک کردن جست‌وجو ↖</button></div>'''
articles=[('coffee-guide.html','brew','راهنمای قهوه','از کدام قهوه شروع کنیم؟','اگر بین اسپرسو، لاته و قهوهٔ دمی مانده‌ای، این راهنمای کوتاه برای توست.','۴ دقیقه'),('slow-mornings.html','bread','حال‌وهوای روز','صبح را کمی آهسته‌تر شروع کن','یک صبح آرام الزاماً وقت زیادی نمی‌خواهد؛ گاهی فقط به چند انتخاب کوچک نیاز دارد.','۳ دقیقه'),('iced-coffee.html','cold-0','طعم‌ها','آیس‌لاته یا کلدبرو؟','دو نوشیدنی خنک با دو روش تهیه و دو تجربهٔ متفاوت از قهوه.','۳ دقیقه')]
def article_cards():
 return ''.join(f'<article class="journal-card reveal"><a href="{url}" class="journal-image">{img(photo,title)}<span class="round-arrow">↖</span></a><div class="article-meta"><span>{cat}</span><span>{time} مطالعه</span></div><h3><a href="{url}">{title}</a></h3><p>{desc}</p></article>' for url,photo,cat,title,desc,time in articles)
def gallery_card(photo,alt,cat,cls=''):
 return f'<button class="gallery-item {cls} reveal" data-gallery="{cat}" data-caption="{alt}">{img(photo,alt)}<span>{alt}<b aria-hidden="true">↗</b></span></button>'
home=f'''<section class="hero"><div class="hero-image">{img('hero','فنجان قهوه در نور گرم و آرام کافه',eager=True)}</div><div class="hero-shade"></div><div class="hero-content">{eyebrow('برای لحظه‌هایی که مال خودت هستند')}<h1>دنیا کمی صبر کند.<br>وقتِ یک فنجان<br><em>مکث</em> است.</h1><p>عطر قهوه، نور آرام و یک جای دنج.<br>گاهی برای بهتر شدن روز، همین‌ها کافی‌ست.</p>{link('menu.html','منوی مکث را ببین','button cream')}<div class="hero-note"><span></span>قهوه‌ات را آهسته بنوش.</div></div><span class="hero-index">۰۱ <i></i> یک قرار ساده</span><a class="hero-scroll" href="#story">داستان از این‌جا شروع می‌شود <span>↓</span></a><div class="hero-stamp" aria-hidden="true">قهوه و زندگی<br><b>✶</b><br>به وقت خودت</div></section><div class="ribbon"><span>قهوه، به وقت تو</span><i>✶</i><span>جایی برای گفت‌وگو</span><i>✶</i><span>یک تکه شیرینی، یک حال خوب</span><i>✶</i><span>کمی دور از شلوغی</span></div>
<section class="section story" id="story"><div class="story-copy reveal">{eyebrow('۰۱ / داستان مکث')}<h2>بعضی جاها،<br>آدم را به <em>ماندن</em> <br>دعوت می‌کنند.</h2><p>مکث، تصور ما از یک کافهٔ دوست‌داشتنی است؛ جایی برای ورق زدن چند صفحه کتاب، دیدن یک دوست قدیمی یا تماشای خیابان از پشت پنجره.</p><p>قهوه این‌جا بهانه است. اصل ماجرا، وقتی‌ست که برای خودت و آدم‌های زندگی‌ات کنار می‌گذاری.</p>{link('about.html','داستان ما را بخوان','text-link')}</div><div class="story-images reveal">{img('interior','فضای روشن کافه با میزهای چوبی')}<div class="small-photo">{img('beans','دانه‌های برشته قهوه')}<span>از عطر اولین دانه<br>تا آخرین جرعه.</span></div><span class="round-stamp" aria-hidden="true">یک جای دنج<br>برای حال خوب<br>✶</span></div></section>
<section class="section home-menu" id="menu"><div class="section-head reveal"><div>{eyebrow('۰۲ / چیزی که امروز می‌چسبد')}<h2>حال امروزت، <em>چه طعمی‌ست؟</em></h2></div>{link('menu.html','دیدن تمام منو','text-link')}</div>{menu_controls(True)}<p class="fine-print">منو و قیمت‌ها نمونه‌اند. قیمت‌ها به هزار تومان است.</p></section>
<section class="feature"><div class="feature-image">{img('cup','یک فنجان قهوه روی میز')}</div><div class="feature-copy reveal">{eyebrow('پیشنهاد مکث')}<span class="feature-star" aria-hidden="true">✶</span><h2>یک قرار ساده:<br>تو، قهوه‌ات<br>و <em>همین لحظه.</em></h2><p>اگر طعم نرم شیر و عطر قهوه را دوست داری، از یک لاته شروع کن. برای روزهای گرم‌تر، آیس‌لاته همان همراه آشناست، با حال‌وهوایی خنک‌تر.</p>{link('menu.html?category=coffee','قهوهٔ من کدام است؟','button cream')}</div></section>
<section class="section"><div class="section-head reveal"><div>{eyebrow('۰۳ / قاب‌هایی از مکث')}<h2>اینجا، <em>عجله نداریم.</em></h2></div>{link('gallery.html','یک دور در کافه بزن','text-link')}</div><div class="home-gallery">{gallery_card('space','گوشهٔ دنج تو','space','tall')}{gallery_card('brew','هنر کوچک هر فنجان','coffee')}{gallery_card('bread','کنار قهوه، کمی شیرینی','food')}</div></section>
<section class="journal-section section"><div class="section-head reveal"><div>{eyebrow('۰۴ / چند خط کنار قهوه')}<h2>خواندنی‌های <em>یک فنجان.</em></h2></div>{link('journal.html','ورق زدن مجله','text-link')}</div><div class="journal-grid">{article_cards()}</div></section>'''
page('index.html','یک فنجان، دور از شتاب','کافه مکث؛ منوی قهوه، صبحانه و شیرینی، قاب‌های کافه و خواندنی‌های یک فنجان.',home)
page('menu.html','منوی قهوه، صبحانه و شیرینی','منوی کافه مکث را بر اساس قهوه گرم، نوشیدنی سرد، صبحانه و شیرینی جست‌وجو کنید.',mast('منوی مکث','هر روز،<br>یک <em>طعم تازه.</em>','از یک اسپرسوی کوتاه تا صبحانه‌ای طولانی؛ این‌جا از سلیقهٔ تو شروع می‌کنیم.','coffee-1')+f'<section class="section menu-page">{menu_controls()}<div class="menu-bottom-note"><span>✶</span><p>قیمت‌ها به هزار تومان و برای نمایش طرح هستند. ترکیبات هر آیتم را در پنجرهٔ جزئیات ببین؛ اگر حساسیت غذایی داری، پیش از سفارش با کافه هماهنگ کن.</p>{link("faq.html","پرسش‌های منو","text-link")}</div></section><section class="pairing section"><div>{eyebrow("همراه‌های خوب")}<h2>کنار قهوه‌ات،<br><em>کمی شیرینی.</em></h2><p>گاهی یک کروسان کره‌ای یا یک برش کیک، همان چیزی است که فنجانت کم دارد.</p>{link("menu.html?category=cake","دیدن شیرینی‌ها","button dark")}</div>{img("bread","نان و شیرینی روی میز")}</section>')
page('about.html','داستان مکث','دربارهٔ ایدهٔ کافه مکث؛ جایی برای قهوه، گفت‌وگو و چند دقیقه دوری از شتاب روز.',mast('داستان مکث','از یک فکر ساده:<br><em>کمی بمان.</em>','چه می‌شد اگر جایی بود که در آن، لازم نبود برای تمام کردن فنجانت عجله کنی؟','interior')+f'''<section class="section story about-story"><div class="story-copy reveal">{eyebrow('یک نام، یک دعوت')}<h2>مکث، فاصلهٔ کوتاهی‌ست<br>میان <em>دو شلوغی.</em></h2><p>کافه‌ای که دوستش داریم، فقط یک منوی خوب ندارد. صندلی‌اش راحت است، نورش چشم را خسته نمی‌کند و صدای گفت‌وگو در آن گم نمی‌شود.</p><p>ایدهٔ مکث از همین تصویر آمده است: فضایی که در آن می‌شود بی‌برنامه نشست، یک نوشیدنی آشنا سفارش داد و برای چند دقیقه، کار بعدی را فراموش کرد.</p><p>این وب‌سایت، نمونه‌ای از هویت و تجربهٔ دیجیتال چنین کافه‌ای است. داستان واقعی، با آدم‌ها و جزئیات کافهٔ شما نوشته می‌شود.</p></div><div class="about-image reveal">{img('beans','بافت دانه‌های برشته قهوه')}<span>هر فنجان، یک بهانه برای کنار هم بودن.</span></div></section><section class="manifesto"><span aria-hidden="true">“</span><blockquote>قرار نیست هر دقیقه را پُر کنیم.<br>بعضی دقیقه‌ها را باید <em>زندگی کرد.</em></blockquote><p>فلسفهٔ مکث</p></section><section class="section"><div class="section-head reveal"><div>{eyebrow('جزئیاتی که دوست داریم')}<h2>حال خوب،<br>در <em>چیزهای کوچک</em> است.</h2></div><p>تصویری از تجربه‌ای که<br>برای مکث در نظر گرفته‌ایم.</p></div><div class="values"><article class="reveal"><span>۰۱ / فنجان</span><h3>طعم، به سلیقهٔ تو</h3><p>منویی روشن و قابل‌فهم، تا بتوانی بدون سردرگمی نوشیدنی موردعلاقه‌ات را پیدا کنی.</p></article><article class="reveal"><span>۰۲ / فضا</span><h3>جا برای نفس کشیدن</h3><p>چوب، نور گرم و فاصله‌های آرام؛ فضایی که عکسش هم تو را به نشستن دعوت کند.</p></article><article class="reveal"><span>۰۳ / آدم‌ها</span><h3>گفت‌وگو از همین‌جا</h3><p>یک میز کوچک می‌تواند شروع یک آشنایی باشد، یا ادامهٔ دوستی‌ای قدیمی.</p></article></div></section>''')
gallery=''.join([gallery_card('space','نور روز، پشت پنجره','space','wide'),gallery_card('coffee-1','یک لاته، پیش از اولین جرعه','coffee'),gallery_card('bread','عطر نان و یک شروع آرام','food'),gallery_card('interior','جایی برای قرارهای طولانی','space','wide'),gallery_card('brew','جزئیات یک فنجان','coffee'),gallery_card('beans','داستان، از دانه شروع می‌شود','coffee'),gallery_card('breakfast-2','صبحی به شیرینی پنکیک','food'),gallery_card('cup','کمی تنها، کمی آرام','coffee','wide')])
page('gallery.html','گالری و حال‌وهوای کافه','قاب‌هایی از فضای کافه، قهوه، صبحانه و شیرینی؛ گالری تصویری مکث.',mast('قاب‌های مکث','بعضی لحظه‌ها،<br><em>دیدنی‌اند.</em>','نور، بافت، عطر؛ چند قاب از حال‌وهوایی که دوست داریم.','space')+f'<section class="section"><div class="filter-tabs" role="group" aria-label="فیلتر گالری"><button class="active" data-filter="all" aria-pressed="true">همهٔ قاب‌ها</button><button data-filter="space" aria-pressed="false">فضای کافه</button><button data-filter="coffee" aria-pressed="false">قهوه و جزئیات</button><button data-filter="food" aria-pressed="false">طعم‌های شیرین</button></div><p class="sr-only" id="gallery-result" role="status"></p><div class="gallery-mosaic">{gallery}</div><p class="fine-print">تصاویر از Unsplash برای نمایش فضای پیشنهادی انتخاب شده‌اند؛ تصاویر کافهٔ واقعی جایگزین می‌شوند.</p></section>')
page('journal.html','مجله و راهنمای قهوه','خواندنی‌های کوتاه مکث دربارهٔ انتخاب قهوه، نوشیدنی‌های سرد و لذت بردن از لحظه‌های آرام.',mast('مجلهٔ مکث','چند خط،<br>کنار <em>قهوه.</em>','برای وقتی که فنجانت هنوز گرم است و دلت کمی خواندن می‌خواهد.','brew')+f'<section class="section"><a class="featured-article reveal" href="coffee-guide.html"><div>{img("brew","قهوه برای یک شروع خوش‌عطر")}</div><div>{eyebrow("پیشنهاد برای شروع / ۴ دقیقه مطالعه")}<h2>از کدام قهوه<br><em>شروع کنیم؟</em></h2><p>نام‌ها قرار نیست انتخاب را سخت کنند. از طعمی که دوست داری شروع کن و فنجانت را پیدا کن.</p><span class="text-link">خواندن مطلب ↖</span></div></a><div class="section-head journal-heading"><h2>یک فنجان <em>خواندنی.</em></h2><span class="fine-print">یادداشت‌های کوتاه مکث</span></div><div class="journal-grid">{article_cards()}</div></section>')
contents=[[
('از سلیقه‌ات شروع کن، نه از اسم‌ها','برای انتخاب قهوه لازم نیست نام همهٔ نوشیدنی‌ها را حفظ باشی. اول مشخص کن نوشیدنی کوتاه و غلیظ دوست داری یا یک فنجان بزرگ‌تر؛ با شیر راحت‌تری یا ترجیح می‌دهی طعم خود قهوه را بشنوی. همین دو سؤال، بخش زیادی از منو را برایت روشن می‌کند.'),
('اسپرسو؛ کوتاه و پررنگ','اسپرسو نوشیدنی کوچکی است که با عبور آب تحت فشار از قهوهٔ آسیاب‌شده تهیه می‌شود. حجم کم آن به معنی کم‌عطر بودن نیست؛ طعم فشرده‌اش می‌تواند برای کسی که تازه قهوه را شروع کرده، تند به نظر برسد. اگر نوشیدنی کوتاه می‌خواهی و طعم مستقیم قهوه را دوست داری، از این‌جا شروع کن.'),
('آمریکانو؛ همان پایه، با آب بیشتر','در آمریکانو، اسپرسو با آب رقیق می‌شود. نوشیدنی نهایی حجم بیشتری دارد و می‌شود آن را آهسته‌تر نوشید. اضافه شدن آب، طعم را رقیق می‌کند؛ مقدار کافئین به تعداد شات‌های اسپرسو بستگی دارد، نه فقط بزرگی فنجان.'),
('لاته و کاپوچینو؛ وقتی شیر را دوست داری','هر دو از اسپرسو و شیر تهیه می‌شوند، اما نسبت‌ها و بافت شیر یکسان نیست. لاته معمولاً شیر بیشتری دارد و نرم‌تر احساس می‌شود؛ کاپوچینو لایهٔ فوم برجسته‌تری دارد. اندازهٔ فنجان و دستور هر کافه هم می‌تواند این تجربه را تغییر دهد.'),
('قهوهٔ دمی؛ فرصتی برای کشف طعم','قهوهٔ دمی خانواده‌ای از روش‌هاست، نه یک طعم ثابت. نوع دانه، میزان برشتگی، آسیاب و روش دم‌آوری روی نتیجه اثر دارند. اگر دوست داری قهوه را جرعه‌جرعه امتحان کنی، از باریستا دربارهٔ طعم دانهٔ همان روز بپرس.'),
('یک سفارش ساده‌تر','می‌توانی خیلی ساده بگویی: «قهوه با شیر می‌خواهم، با طعم متعادل» یا «بدون شیر، یک فنجان بزرگ‌تر دوست دارم». توضیح سلیقه، اغلب از انتخاب کردن یک نام ناآشنا کمک بیشتری می‌کند.')],
[
('اولین کار، لزوماً یک کار نیست','صبح بعضی روزها پیش از آن‌که از تخت بلند شویم، با پیام‌ها شروع شده است. یک تغییر کوچک این است که اولین چند دقیقه را به کاری بدهیم که خودمان انتخاب کرده‌ایم: باز کردن پنجره، نوشیدن آب یا آماده کردن صبحانه.'),
('یک گوشهٔ کوچک برای صبحانه','لازم نیست میز مفصلی بچینیم. یک بشقاب، تکه‌ای نان و نوشیدنی دلخواه کافی‌ست. نشستن برای خوردن، حتی اگر کوتاه باشد، با لقمه‌ای که در راه می‌خوریم تجربهٔ متفاوتی دارد.'),
('فنجان را بهانه کن','تا نوشیدنی آماده می‌شود، چند دقیقه از روز در اختیار توست. می‌توانی به صدای آب گوش بدهی، صفحه‌ای بخوانی یا فقط منتظر بمانی. قرار نیست این زمان هم حتماً نتیجه‌ای داشته باشد.'),
('برنامه‌ای که جا برای تغییر دارد','همهٔ صبح‌ها شبیه هم نیستند. بعضی روزها وقت یک صبحانهٔ طولانی هست، بعضی روزها فقط یک جرعه پیش از رفتن. هدف، ساختن یک آیین بی‌نقص نیست؛ پیدا کردن لحظه‌ای کوچک است که شروع روز را کمی خوشایندتر کند.')],
[
('دو راه برای رسیدن به یک نوشیدنی سرد','اسم هر دو کنار یخ به چشم می‌خورد، اما آیس‌لاته و کلدبرو از یک مسیر به فنجان نمی‌رسند. یکی بر پایهٔ اسپرسو و شیر است؛ دیگری با زمان بیشتر و آب سرد یا هم‌دمای محیط عصاره‌گیری می‌شود.'),
('آیس‌لاته چیست؟','آیس‌لاته معمولاً از اسپرسو، شیر سرد و یخ تهیه می‌شود. شیر، بافت و طعم نوشیدنی را نرم‌تر می‌کند. اگر لاتهٔ گرم دوست داری، نسخهٔ سرد آن انتخاب آشنایی برای شروع است.'),
('کلدبرو چطور تهیه می‌شود؟','برای کلدبرو، قهوه برای چندین ساعت در آب سرد یا هم‌دمای محیط می‌ماند و سپس صاف می‌شود. دستور تهیه، زمان و نسبت قهوه به آب بین کافه‌ها متفاوت است. گاهی عصاره به صورت غلیظ آماده و پیش از سرو با آب یا شیر رقیق می‌شود.'),
('کدام قوی‌تر است؟','از سرد بودن یا رنگ نوشیدنی نمی‌شود مقدار کافئین را تشخیص داد. تعداد شات اسپرسو در آیس‌لاته و غلظت و حجم کلدبرو تعیین‌کننده‌اند. برای مقایسهٔ دقیق، باید دستور همان کافه را بدانیم.'),
('انتخاب بر اساس طعم','اگر شیر و بافت نرم را دوست داری، آیس‌لاته را امتحان کن. اگر می‌خواهی قهوه را بدون شیر تجربه کنی، دربارهٔ طعم کلدبرو بپرس. هیچ‌کدام برندهٔ همیشگی نیست؛ سلیقهٔ تو و دستور تهیه، انتخاب را مشخص می‌کند.')]]
for idx,(url,photo,cat,title,desc,time) in enumerate(articles):
 toc=''.join(f'<a href="#part-{i}">{h}</a>' for i,(h,_) in enumerate(contents[idx]))
 paras=''.join(f'<section id="part-{i}"><h2>{h}</h2><p>{p}</p></section>' for i,(h,p) in enumerate(contents[idx]))
 page(url,title,desc,f'''<section class="article-hero section"><div class="breadcrumbs"><a href="index.html">خانه</a><span>/</span><a href="journal.html">مجلهٔ مکث</a></div>{eyebrow(cat+' / '+time+' مطالعه')}<h1>{title}</h1><p>{desc}</p>{img(photo,title,eager=True)}</section><div class="article-layout section"><aside><span class="eyebrow">در این یادداشت</span>{toc}<button class="text-link share-button">اشتراک‌گذاری مطلب ↗</button></aside><article class="article-body">{paras}<div class="article-end">{eyebrow('یادداشت تحریریهٔ مکث')}<p>این مطلب برای راهنمایی عمومی و تکمیل نمونه‌کار نوشته شده است.</p>{link('menu.html','حالا منو را ببین','text-link')}</div></article></div><section class="section related"><div class="section-head"><h2>یک صفحهٔ <em>دیگر.</em></h2>{link('journal.html','تمام یادداشت‌ها','text-link')}</div><div class="journal-grid">{article_cards()}</div></section>''')
faqs=[('menu','چطور نوشیدنی مناسب سلیقه‌ام را انتخاب کنم؟','اگر نوشیدنی با شیر دوست داری، لاته یا کاپوچینو را ببین. برای قهوهٔ بدون شیر، اسپرسو و قهوهٔ دمی نقطهٔ شروع خوبی هستند. در صفحهٔ منو روی هر آیتم بزن تا توضیحاتش را ببینی.'),('menu','قیمت‌های سایت واقعی هستند؟','خیر. این نسخه یک نمونه‌کار است و نام کافه، قیمت‌ها و ترکیب آیتم‌ها برای نمایش طراحی پیشنهاد شده‌اند. پیش از استفادهٔ واقعی، منو باید توسط صاحب کافه تأیید و به‌روزرسانی شود.'),('menu','برای حساسیت غذایی چه کاری انجام بدهم؟','کیک‌ها، شیرینی‌ها و نوشیدنی‌ها ممکن است حاوی شیر، تخم‌مرغ، گلوتن یا مغزها باشند. اطلاعات نمونهٔ سایت جای تأیید کافه را نمی‌گیرد؛ پیش از سفارش، مواد و احتمال تماس متقاطع را با کارکنان بررسی کن.'),('visit','آیا می‌توانم از سایت میز رزرو کنم؟','در این نسخه رزرو آنلاین فعال نیست. صفحهٔ «برای یک قرار» فقط یک خلاصهٔ شخصی از برنامهٔ دیدارت می‌سازد. هیچ درخواستی برای کافه ارسال نمی‌شود و میزی تأیید یا نگه داشته نخواهد شد.'),('visit','آدرس و ساعت کاری کجاست؟','این سایت برای یک کافهٔ واقعی با نشانی مشخص ساخته نشده است. محل، ساعت کاری و اطلاعات تماس واقعی در زمان شخصی‌سازی در صفحهٔ تماس اضافه می‌شوند.'),('visit','برای کار با لپ‌تاپ یا قرار گروهی مناسب است؟','در این نمونه، امکاناتی مثل وای‌فای، پریز، ظرفیت گروه و قوانین استفاده تأیید نشده‌اند. بعد از مشخص شدن کافه، شرایط واقعی در این بخش درج می‌شود.'),('site','تصاویر مربوط به کافهٔ واقعی هستند؟','تصاویر از Unsplash برای نشان دادن فضای بصری پیشنهادی انتخاب شده‌اند و به مکان یا محصولات یک کافهٔ مشخص اشاره ندارند.'),('site','اطلاعات من در سایت ذخیره می‌شود؟','این نسخه حساب کاربری، پرداخت و فرم ارسال اطلاعات ندارد. جست‌وجو و برنامه‌ریزی قرار در مرورگر انجام می‌شوند و به صاحب کافه ارسال نمی‌شوند. جزئیات بیشتر را در صفحهٔ حریم خصوصی ببین.')]
def faq_items(group=None):
 return ''.join(f'<details class="faq-item reveal"><summary><span>{q}</span><b aria-hidden="true">+</b></summary><p>{a}</p></details>' for cat,q,a in faqs if group is None or cat==group)
page('faq.html','پرسش‌های متداول','پاسخ پرسش‌های مربوط به منو، برنامه‌ریزی قرار، تصاویر و امکانات نمونه‌کار کافه مکث.',mast('پرسش‌های متداول','پیش از فنجان اول،<br><em>بیشتر بدان.</em>','چند پاسخ روشن به سؤال‌هایی که ممکن است برایت پیش بیاید.','coffee-3')+f'''<section class="section faq-layout"><aside class="faq-nav"><a href="#menu-questions">منو و طعم‌ها ↙</a><a href="#visit-questions">قرار در کافه ↙</a><a href="#site-questions">دربارهٔ سایت ↙</a></aside><div><section class="faq-group" id="menu-questions"><h2>منو و طعم‌ها</h2>{faq_items('menu')}</section><section class="faq-group" id="visit-questions"><h2>قرار در کافه</h2>{faq_items('visit')}</section><section class="faq-group" id="site-questions"><h2>دربارهٔ سایت</h2>{faq_items('site')}</section></div></section>''')
page('contact.html','تماس و نشانی کافه','اطلاعات تماس و موقعیت کافه مکث، وضعیت نمونه‌کار و راه‌های برنامه‌ریزی یک دیدار.',mast('تماس و نشانی','قرارمان،<br><em>یک جای آرام.</em>','یک دیدار خوب، با پیدا کردن یک جای خوب شروع می‌شود.','interior')+f'''<section class="section contact-layout"><div class="contact-copy reveal">{eyebrow('برای آشنایی بیشتر')}<h2>پیش از آمدن،<br>از این‌جا <em>شروع کن.</em></h2><p>مکث در حال حاضر یک نمونه‌کار است. پس از انتخاب کافهٔ واقعی، نشانی، تلفن، ساعت کاری و موقعیت نقشه در این صفحه قرار می‌گیرند.</p><div class="contact-detail"><span>۰۱ / نشانی</span><h3>منتظر نشانی کافهٔ شما</h3><p>مکان واقعی هنوز معرفی نشده است.</p></div><div class="contact-detail"><span>۰۲ / ساعت دیدار</span><h3>با برنامهٔ کاری شما</h3><p>روزها و ساعت‌های فعالیت پس از تأیید کافه درج می‌شوند.</p></div><div class="contact-detail"><span>۰۳ / گفت‌وگو</span><h3>تلفن و شبکه‌های اجتماعی</h3><p>لینک و شمارهٔ ساختگی نمایش داده نمی‌شود؛ اطلاعات تأییدشده جایگزین می‌شوند.</p></div></div><div class="contact-visual reveal">{img('space','یک میز خالی کنار پنجرهٔ کافه')}<div class="location-note"><span>⌖</span><div><h3>یک نقطهٔ خوب روی نقشه</h3><p>نقشه پس از دریافت موقعیت واقعی اضافه می‌شود.</p></div></div></div></section><section class="contact-next section"><div>{eyebrow('تا قرار بعدی')}<h2>حالا، <em>چه می‌چسبد؟</em></h2></div><div>{link('menu.html','اول منو را ببینم','button dark')}{link('visit.html','برای یک قرار برنامه بریزم','button outline')}</div></section>''')
page('visit.html','برنامه‌ریزی یک قرار','یک برنامهٔ شخصی برای دیدار در کافه بسازید. این نمونه‌کار رزرو آنلاین یا ارسال درخواست ندارد.',mast('برای یک قرار','بهانه‌اش قهوه،<br><em>اصلش دیدار.</em>','تنها با یک کتاب، یا کنار یک دوست؛ برای مکث بعدی‌ات برنامه بچین.','breakfast-0')+'''<section class="section visit-layout"><div class="visit-copy reveal"><span class="eyebrow">قرار خوب، بدون عجله</span><h2>چند دقیقه را، <br>برای <em>خودت</em> کنار بگذار.</h2><p>از این فرم برای ساختن خلاصهٔ برنامهٔ شخصی‌ات استفاده کن. بعد می‌توانی متنش را کپی کنی و برای همراهت بفرستی.</p><div class="notice"><span>i</span><p><strong>این فرم رزرو میز نیست.</strong> اطلاعات به کافه ارسال یا در سرور ذخیره نمی‌شود. هیچ میزی رزرو و هیچ ظرفیتی تأیید نخواهد شد.</p></div><a class="text-link" href="faq.html#visit-questions">پرسش‌های مربوط به قرار ↖</a></div><div class="planner"><form id="visit-form"><h3>مکث بعدی من</h3><div class="form-row"><label>روز قرار<input type="date" id="visit-date" required></label><label>ساعت پیشنهادی<input type="time" id="visit-time" required value="17:00"></label></div><div class="form-row"><label>چند نفریم؟<select id="visit-guests"><option value="۱ نفر">فقط خودم</option><option value="۲ نفر" selected>دو نفر</option><option value="۳ نفر">سه نفر</option><option value="۴ نفر">چهار نفر</option><option value="۵ نفر یا بیشتر">پنج نفر یا بیشتر</option></select></label><label>حال‌وهوای قرار<select id="visit-mood"><option>یک گفت‌وگوی دوستانه</option><option>کتاب و خلوت</option><option>صبحانه و شروع روز</option><option>یک قرار دونفره</option></select></label></div><button class="button dark" type="submit">ساختن برنامهٔ من <span>↖</span></button><p class="fine-print">فقط یک خلاصهٔ شخصی؛ بدون ثبت رزرو.</p></form><div id="visit-summary" hidden role="status"><span class="eyebrow">برنامهٔ تو آماده است</span><h3>به وقت یک مکث.</h3><p id="summary-text"></p><p class="fine-print">این برنامه تأییدیهٔ رزرو نیست؛ برای هماهنگی واقعی باید با کافه تماس بگیری.</p><button class="button dark" id="copy-plan">کپی متن قرار ↗</button><button class="text-link" id="edit-plan">ویرایش برنامه ↖</button></div></div></section>''')
page('privacy.html','حریم خصوصی','نحوهٔ پردازش اطلاعات، تصاویر، جست‌وجو و اشتراک‌گذاری در نسخهٔ استاتیک کافه مکث.',mast('حریم خصوصی','شفاف و <em>ساده.</em>','دربارهٔ اطلاعاتی که در این نسخه از سایت استفاده می‌شوند.','beans')+'''<article class="section legal article-body"><h2>یک وب‌سایت استاتیک</h2><p>این نسخه روی GitHub Pages میزبانی می‌شود و حساب کاربری، خرید، پرداخت، ثبت رزرو یا فرم ارسال پیام ندارد. ابزار تحلیل رفتار، تبلیغات و کوکی اختصاصی نیز در کد سایت قرار داده نشده است.</p><h2>جست‌وجو و برنامه‌ریزی قرار</h2><p>عبارت جست‌وجوی منو و اطلاعات برنامهٔ دیدار فقط در حافظهٔ همان صفحه پردازش می‌شوند. این سایت آن‌ها را به سرور ارسال و در حافظهٔ دائمی مرورگر ذخیره نمی‌کند. با بستن یا بارگذاری مجدد صفحه، برنامهٔ ساخته‌شده پاک می‌شود.</p><h2>کپی و اشتراک‌گذاری</h2><p>کپی متن تنها پس از زدن دکمهٔ مربوط انجام می‌شود. اشتراک‌گذاری صفحه در مرورگرهای پشتیبانی‌شده، پنجرهٔ سیستم را باز می‌کند و انتخاب مقصد و ارسال در اختیار خودت است.</p><h2>میزبانی و لینک‌های بیرونی</h2><p>میزبان سایت ممکن است اطلاعات فنی درخواست‌ها، مانند نشانی IP، را طبق سیاست‌های خود پردازش کند. تصاویر و فونت نسخهٔ منتشرشده همراه فایل‌های سایت میزبانی می‌شوند. با باز کردن لینک بیرونی، مانند وب‌سایت طراح، سیاست‌های مقصد اعمال می‌شوند.</p><h2>دربارهٔ محتوای نمونه</h2><p>نام کافه، منو، قیمت‌ها و برنامه‌ریزی دیدار، بخش‌هایی از یک نمونه‌کار هستند. اگر سایت به خدمات واقعی متصل شود، این صفحه باید متناسب با نوع اطلاعات و خدمات جدید به‌روزرسانی شود.</p></article>''')
page('404.html','صفحه پیدا نشد','صفحهٔ موردنظر پیدا نشد. به خانه یا منوی کافه مکث برگردید.','''<section class="not-found section"><span class="error-number" aria-hidden="true">۴۰۴</span><span class="eyebrow">انگار کمی از مسیر دور شدیم.</span><h1>این‌جا فنجانی نیست؛<br><em>برگردیم به مکث.</em></h1><p>ممکن است آدرس تغییر کرده باشد یا صفحه‌ای با این نام وجود نداشته باشد.</p><div><a class="button dark" href="/cafeshop/">برگشت به خانه ↖</a><a class="button outline" href="/cafeshop/menu.html">دیدن منوی کافه ↖</a></div></section>''')
