f=P/'404.html';s=f.read_text();s=s.replace('<head>','<head><base href="/cafeshop/">');f.write_text(s)
urls=['index.html','menu.html','about.html','gallery.html','journal.html','contact.html','visit.html','faq.html','privacy.html']+[a[0] for a in articles]
